import NextAuth from "next-auth";
import Credentials from "next-auth/providers/credentials";
import Google from "next-auth/providers/google";
import { findOrCreateOAuthUser, getUserByEmail, verifyPassword } from "@/lib/users";
import { consumeMagicLinkToken } from "@/lib/magic-links";

export const { handlers, signIn, signOut, auth } = NextAuth({
  providers: [
    Google({
      clientId: process.env.GOOGLE_CLIENT_ID,
      clientSecret: process.env.GOOGLE_CLIENT_SECRET,
    }),
    Credentials({
      id: "credentials",
      name: "Email and password",
      credentials: {
        email: { label: "Email", type: "email" },
        password: { label: "Password", type: "password" },
      },
      authorize: async (credentials) => {
        const email = credentials?.email;
        const password = credentials?.password;
        if (typeof email !== "string" || typeof password !== "string") return null;

        const user = await verifyPassword(email, password);
        if (!user) return null;

        return { id: user.id, email: user.email, name: user.name };
      },
    }),
    Credentials({
      // A second, separate Credentials provider rather than NextAuth's
      // built-in Email provider: that one requires a database Adapter to
      // persist verification tokens, which this app (in-memory user store,
      // JWT sessions) doesn't have. The token itself is minted and emailed
      // by /api/auth/magic-link, then redeemed here exactly like a password.
      id: "magic-link",
      name: "Magic Link",
      credentials: {
        token: { label: "Token", type: "text" },
      },
      authorize: async (credentials) => {
        const token = credentials?.token;
        if (typeof token !== "string" || !token) return null;

        const email = consumeMagicLinkToken(token);
        if (!email) return null;

        const user = await findOrCreateOAuthUser({ email, name: email.split("@")[0] });
        return { id: user.id, email: user.email, name: user.name };
      },
    }),
  ],
  session: { strategy: "jwt" },
  pages: {
    signIn: "/signin",
  },
  callbacks: {
    async signIn({ user, account }) {
      // Provision (or link to) a local user record on first Google sign-in.
      if (account?.provider === "google" && user.email) {
        await findOrCreateOAuthUser({
          email: user.email,
          name: user.name ?? user.email,
        });
      }
      return true;
    },
    async jwt({ token, user }) {
      if (user?.email) {
        // Fresh sign-in (any provider): stamp the token with the account's
        // current session version so later requests can detect a revocation.
        const dbUser = await getUserByEmail(user.email);
        token.sessionVersion = dbUser?.sessionVersion;
        return token;
      }

      if (typeof token.email !== "string") return token;

      // Every subsequent request: if the account's session version has moved
      // on — from "sign out of all devices", a password change, or the
      // account being deleted — invalidate this token by dropping the
      // version. The session callback below turns that into a logged-out
      // session.
      const dbUser = await getUserByEmail(token.email);
      if (!dbUser || dbUser.sessionVersion !== token.sessionVersion) {
        token.sessionVersion = undefined;
      }
      return token;
    },
    async session({ session, token }) {
      if (!token.sessionVersion) {
        return { ...session, user: undefined };
      }
      return session;
    },
  },
});

