        // Fresh sign-in (any provider): stamp the token with the account's
        // current session version so later requests can detect a revocation.
        const dbUser = await getUserByEmail(user.email);
        token.sessionVersion = dbUser?.sessionVersion;
        return token;
      }

      if (typeof token.email !== "string") return token;

      // Every subsequent request: if the account's session version has moved
      // on — from "sign out of all devices", a password change, or the
      // account being deleted — invalidate this token by dropping the
      // version. The session callback below turns that into a logged-out
      // session.
      const dbUser = await getUserByEmail(token.email);
      if (!dbUser || dbUser.sessionVersion !== token.sessionVersion) {
        token.sessionVersion = undefined;
      }
      return token;
    },
    async session({ session, token }) {
      if (!token.sessionVersion) {
        return { ...session, user: undefined };
      }
      return session;
    },
  },
});

