import { NextResponse } from "next/server";
import { createMagicLinkToken } from "@/lib/magic-links";
import { sendMagicLinkEmail } from "@/lib/email";

export async function POST(req: Request) {
  const body = await req.json().catch(() => null);
  const email = typeof body?.email === "string" ? body.email.trim().toLowerCase() : "";

  if (!email || !email.includes("@")) {
    return NextResponse.json({ error: "Enter a valid email address." }, { status: 400 });
  }

  const token = createMagicLinkToken(email);
  const url = new URL("/auth/magic-link", req.url);
  url.searchParams.set("token", token);

  await sendMagicLinkEmail(email, url.toString());

  const isDev = process.env.NODE_ENV !== "production";
  return NextResponse.json({
    ok: true,
    // Only surfaced outside production, so magic-link sign-in is testable
    // without a real RESEND_API_KEY configured.
    ...(isDev ? { devLink: url.toString() } : {}),
  });
}

