"use client";

import { useState, type FormEvent } from "react";
import { signIn, signOut } from "next-auth/react";

const inputClass =
  "w-full rounded-md border border-black/[.08] bg-transparent px-3 py-2 text-sm outline-none focus:border-black/40 dark:border-white/[.145] dark:focus:border-white/40";

const sectionClass =
  "space-y-4 rounded-xl border border-black/[.08] p-6 dark:border-white/[.145]";

export function AccountForms({ email, hasPassword }: { email: string; hasPassword: boolean }) {
  return (
    <div className="mt-8 space-y-6">
      <PasswordSection email={email} hasPassword={hasPassword} />
      <SignOutEverywhereSection />
      <DeleteAccountSection />
    </div>
  );
}

function PasswordSection({ email, hasPassword }: { email: string; hasPassword: boolean }) {
  const [currentPassword, setCurrentPassword] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);
  const [loading, setLoading] = useState(false);

  async function handleSubmit(e: FormEvent) {
    e.preventDefault();
    setError(null);
    setSuccess(false);

    if (newPassword !== confirmPassword) {
      setError("New passwords don't match.");
      return;
    }

    setLoading(true);

    const res = await fetch("/api/account/password", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ currentPassword, newPassword }),
    });
    const data = await res.json().catch(() => null);

    if (!res.ok) {
      setError(data?.error ?? "Something went wrong.");
      setLoading(false);
      return;
    }

    // Changing the password bumped the session version server-side, which
    // invalidates this browser's session too — re-authenticate right away so
    // the user isn't unexpectedly signed out after a successful change.
    await signIn("credentials", { email, password: newPassword, redirect: false });

    setCurrentPassword("");
    setNewPassword("");
    setConfirmPassword("");
    setSuccess(true);
    setLoading(false);
  }

  return (
    <section className={sectionClass}>
      <div>
        <h2 className="text-lg font-medium">{hasPassword ? "Change password" : "Set a password"}</h2>
        {!hasPassword && (
          <p className="mt-1 text-sm opacity-70">
            Your account currently has no password — you sign in with Google or a magic link. Set
            one to also enable email/password sign-in.
          </p>
        )}
      </div>

      <form onSubmit={handleSubmit} className="space-y-4">
        {hasPassword && (
          <div className="space-y-1">
            <label htmlFor="currentPassword" className="text-sm font-medium">
              Current password
            </label>
            <input
              id="currentPassword"
              type="password"
              required
              value={currentPassword}
              onChange={(e) => setCurrentPassword(e.target.value)}
              className={inputClass}
            />
          </div>
        )}
        <div className="space-y-1">
          <label htmlFor="newPassword" className="text-sm font-medium">
            New password
          </label>
          <input
            id="newPassword"
            type="password"
            required
            minLength={8}
            value={newPassword}
            onChange={(e) => setNewPassword(e.target.value)}
            className={inputClass}
          />
        </div>
        <div className="space-y-1">
          <label htmlFor="confirmPassword" className="text-sm font-medium">
            Confirm new password
          </label>
          <input
            id="confirmPassword"
            type="password"
            required
            minLength={8}
            value={confirmPassword}
            onChange={(e) => setConfirmPassword(e.target.value)}
            className={inputClass}
          />
        </div>

        {error && <p className="text-sm text-red-600 dark:text-red-400">{error}</p>}
        {success && (
          <p className="text-sm text-green-600 dark:text-green-400">Password updated.</p>
        )}

        <button
          type="submit"
          disabled={loading}
          className="flex h-10 items-center justify-center rounded-full bg-foreground px-5 text-sm font-medium text-background transition-colors hover:bg-[#383838] disabled:opacity-60 dark:hover:bg-[#ccc]"
        >
          {loading ? "Saving…" : hasPassword ? "Update password" : "Set password"}
        </button>
      </form>
    </section>
  );
}

function SignOutEverywhereSection() {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function handleSignOutEverywhere() {
    setError(null);
    setLoading(true);

    const res = await fetch("/api/account/sign-out-everywhere", { method: "POST" });

    if (!res.ok) {
      const data = await res.json().catch(() => null);
      setError(data?.error ?? "Something went wrong.");
      setLoading(false);
      return;
    }

    await signOut({ callbackUrl: "/signin" });
  }

  return (
    <section className={sectionClass}>
      <div>
        <h2 className="text-lg font-medium">Sign out of all devices</h2>
        <p className="mt-1 text-sm opacity-70">
          Ends every signed-in session for this account, including this one. You&apos;ll need to
          sign in again everywhere.
        </p>
      </div>

      {error && <p className="text-sm text-red-600 dark:text-red-400">{error}</p>}

      <button
        type="button"
        onClick={handleSignOutEverywhere}
        disabled={loading}
        className="flex h-10 items-center justify-center rounded-full border border-black/[.08] px-5 text-sm font-medium transition-colors hover:bg-black/[.04] disabled:opacity-60 dark:border-white/[.145] dark:hover:bg-[#1a1a1a]"
      >
        {loading ? "Signing out…" : "Sign out everywhere"}
      </button>
    </section>
  );
}

function DeleteAccountSection() {
  const [confirmText, setConfirmText] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const canDelete = confirmText === "DELETE";

  async function handleDelete() {
    if (!canDelete) return;
    setError(null);
    setLoading(true);

    const res = await fetch("/api/account/delete", { method: "POST" });

    if (!res.ok) {
      const data = await res.json().catch(() => null);
      setError(data?.error ?? "Something went wrong.");
      setLoading(false);
      return;
    }

    await signOut({ callbackUrl: "/" });
  }

  return (
    <section className={`${sectionClass} border-red-600/30`}>
      <div>
        <h2 className="text-lg font-medium text-red-600 dark:text-red-400">Delete account</h2>
        <p className="mt-1 text-sm opacity-70">
          Permanently deletes your account and signs you out everywhere. This can&apos;t be undone.
        </p>
      </div>

      <div className="space-y-1">
        <label htmlFor="confirmDelete" className="text-sm font-medium">
          Type DELETE to confirm
        </label>
        <input
          id="confirmDelete"
          type="text"
          value={confirmText}
          onChange={(e) => setConfirmText(e.target.value)}
          className={inputClass}
        />
      </div>

      {error && <p className="text-sm text-red-600 dark:text-red-400">{error}</p>}

      <button
        type="button"
        onClick={handleDelete}
        disabled={!canDelete || loading}
        className="flex h-10 items-center justify-center rounded-full bg-red-600 px-5 text-sm font-medium text-white transition-colors hover:bg-red-700 disabled:opacity-40"
      >
        {loading ? "Deleting…" : "Delete my account"}
      </button>
    </section>
  );
}

