"use client";

import { Suspense, useEffect, useState } from "react";
import { signIn } from "next-auth/react";
import { useSearchParams } from "next/navigation";
import Link from "next/link";

export default function MagicLinkPage() {
  return (
    <Suspense>
      <MagicLinkVerifier />
    </Suspense>
  );
}

function MagicLinkVerifier() {
  const searchParams = useSearchParams();
  const token = searchParams.get("token");
  const [status, setStatus] = useState<"verifying" | "error">("verifying");

  useEffect(() => {
    if (!token) {
      setStatus("error");
      return;
    }

    let cancelled = false;

    signIn("magic-link", { token, redirect: false, callbackUrl: "/dashboard" }).then((res) => {
      if (cancelled) return;
      if (res?.error) {
        setStatus("error");
        return;
      }
      window.location.href = res?.url ?? "/dashboard";
    });

    return () => {
      cancelled = true;
    };
  }, [token]);

  return (
    <div className="flex flex-1 items-center justify-center bg-zinc-50 px-4 py-16 dark:bg-black">
      <div className="w-full max-w-sm space-y-4 rounded-xl border border-black/[.08] bg-white p-8 text-center dark:border-white/[.145] dark:bg-zinc-950">
        {status === "verifying" ? (
          <p className="text-sm text-zinc-600 dark:text-zinc-400">Signing you in…</p>
        ) : (
          <>
            <h1 className="text-lg font-semibold text-black dark:text-zinc-50">
              This link doesn&apos;t work
            </h1>
            <p className="text-sm text-zinc-600 dark:text-zinc-400">
              It may have expired or already been used. Magic links are valid for 15 minutes and
              can only be used once.
            </p>
            <Link href="/signin" className="text-sm font-medium underline">
              Back to sign in
            </Link>
          </>
        )}
      </div>
    </div>
  );
}

